// @ts-nocheck
import * as React from 'react';
import ListSubheader from '@mui/material/ListSubheader';
import List from '@mui/material/List';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemIcon from '@mui/material/ListItemIcon';
import ListItemText from '@mui/material/ListItemText';
import Collapse from '@mui/material/Collapse';
import InboxIcon from '@mui/icons-material/MoveToInbox';
import DraftsIcon from '@mui/icons-material/Drafts';
import SendIcon from '@mui/icons-material/Send';
import ExpandLess from '@mui/icons-material/ExpandLess';
import ExpandMore from '@mui/icons-material/ExpandMore';
import StarBorder from '@mui/icons-material/StarBorder';
import Tab from '@mui/material/Tab';
import Box from '@mui/material/Box';
import CustomizedMenus from './DDmenu';
import Tabs, { tabsClasses } from '@mui/material/Tabs';
import { useEffect, useState } from 'react';

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function CustomTabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`simple-tabpanel-${index}`}
      aria-labelledby={`simple-tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
}



export default function BasicTabs(props: props) {
  
  const [open, setOpen] = React.useState(false);
  const [data, setData] = useState(null);
  const [value, setValue] = React.useState(0);

  const handleClick = () => {
    setOpen(!open);
  };

  useEffect(() => {
      fetch('toBeUsed/productGeneralization.json')
      .then(response => response.json())
      .then(data => setData(data))
      .catch(error => console.error('Error fetching data:', error));
  }, []);


  function a11yProps(index: number) {
    return {
      id: `simple-tab-${index}`,
      'aria-controls': `simple-tabpanel-${index}`,
    };
  }


  const handleChange = (event: React.SyntheticEvent, newValue: number) => {
    setValue(newValue);
  };

  if (!data) {
    return <div>Loading...</div>;
  } 

  return (
    <Box sx={{ width: '100%'}}>
      <Box sx={{ borderColor: 'divider' }}>
        <Tabs 
        sx={{
          [`& .${tabsClasses.scrollButtons}`]: {
            '&.Mui-disabled': { opacity: 0.3 },
          },
        }}
      
        variant="scrollable"  scrollButtons value={value} onChange={handleChange} aria-label="basic tabs example">
        {data.map(item => (
            <Tab sx={{ width: '6vw'}} label={item.PC} {...a11yProps(item.value)} />
        ))}
        </Tabs>
      </Box>

        <CustomTabPanel value={value} index={0}>
          <CustomizedMenus props = {data.at(0)}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={1}>
          <CustomizedMenus props = {data.at(1)}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={2}>
          <CustomizedMenus props = {data.at(2)}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={3}>
          <CustomizedMenus props = {data.at(3)}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={4}>
          <CustomizedMenus props = {data.at(4)}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={5}>
          <CustomizedMenus props = {data.at(5)}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={6}>
          <CustomizedMenus props = {data.at(6)}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={7}>
          <CustomizedMenus props = {data.at(7)}/>
        </CustomTabPanel>
  
    </Box>
  );
}

